create table xxcus.xxfnd_audit_log (
    audit_log_id  number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    table_name    varchar2(128 byte) not null enable,
    pk_value      varchar2(400 byte) not null enable,
    action_code   varchar2(1 byte) not null enable,
    column_name   varchar2(128 byte),
    old_value     varchar2(4000 byte),
    new_value     varchar2(4000 byte),
    change_reason varchar2(1000 byte),
    changed_by    varchar2(255 byte) not null enable,
    changed_date  timestamp(6) default systimestamp not null enable
);

alter table xxcus.xxfnd_audit_log
    add constraint xxfnd_audit_log_ck1
        check ( action_code in ( 'I', 'U', 'D' ) ) enable;

alter table xxcus.xxfnd_audit_log
    add constraint xxfnd_audit_log_pk primary key ( audit_log_id )
        using index enable;


